create or replace function public.admin_update_order_payment(p_order_id uuid, p_payment_status text) returns uuid language plpgsql security definer set search_path = public as 2238 declare v_order public.orders%rowtype; v_item record; begin if auth.uid() is null or not public.is_admin() then raise exception 'not_authorized'; end if; if p_payment_status not in ('confirmed','rejected') then raise exception 'invalid_payment_status'; end if; select * into v_order from public.orders where id=p_order_id for update; if not found then raise exception 'order_not_found'; end if; if v_order.payment_status <> 'pending' then raise exception 'payment_already_processed'; end if; update public.orders set payment_status=p_payment_status, status=case when p_payment_status='confirmed' then 'preparing' else 'pending' end, pickup_code=case when p_payment_status='rejected' then null else pickup_code end where id=p_order_id; if p_payment_status='rejected' then for v_item in select product_id, quantity from public.order_items where order_id=p_order_id loop update public.products set stock=stock+v_item.quantity where id=v_item.product_id; end loop; end if; return p_order_id; end; 2238; revoke all on function public.admin_update_order_payment(uuid,text) from public; grant execute on function public.admin_update_order_payment(uuid,text) to authenticated;